const STORAGE_KEY = 'little-days-v1';
const familyStore = LittleDaysFamily.create({legacyKey:STORAGE_KEY});
let state = loadState();
let selectedDay = 1;
let editingEntryId = null;
let syncTimer = null;
let syncRunning = false;
let installPrompt = null;

/** @type {(id:string)=>any} */
const $ = (id) => document.getElementById(id);
/** @type {any} */
const els = ['babyId','babyName','birthDate','birthTime','babySex','gestationalWeeks','gestationalDays','birthWeight','birthLength','birthHead','weightDisplayUnit','lengthDisplayUnit','babySelector','activeBabyId','addBaby','syncDevices','syncSummary','installButton','setupCard','tracker','babyDay','dayWindow','setupError','saveStatus','daySelect','prevDay','nextDay','feedCount','wetCount','soilCount','tempCount','feedDetail','wetDetail','soilDetail','tempDetail','summaryTitle','timeline','entryDialog','entryForm','entryType','entryDate','entryTime','dialogTitle','dialogEyebrow','feedFields','soilFields','tempFields','growthFields','temperature','tempUnit','tempMethod','tempAssessment','breastDetails','bottleDetails','feedingObservationDetails','breastObservationFields','bottleObservationFields','swallowing','latch','afterFeed','bottleResponse','duration','side','amount','milkType','soilColor','weight','weightUnit','height','heightUnit','headCircumference','headUnit','includeInGrowthAnalysis','notes','entryError','printReport','chartFeature','chartRange','chartLegend','chart','chartTooltip','dailyChartFeature','dailyChartRange','dailyChartLegend','dailyChart','dailyChartTooltip','growthAnalysis','includeGrowthPdf','editGrowthProfile','growthProfileNotice','growthSignals','growthSummary','birthRecovery','growthChartMetric','growthChartMode','headChartOption','growthChart','growthChartTooltip','growthTrajectory','growthCareContext','weightCareContext','growthQuality','feedingGuidance','includeFeedingPdf','openFeedingPlan','clinicalPlanBanner','feedingStatusCard','feedingStatusIcon','feedingStatusLabel','feedingStatusTitle','feedingStatusText','feedingCoverage','feedingTrackingComplete','diaperTrackingComplete','feedingMetrics','feedingReasonList','feedingActions','feedingSafetyNote','feedingWhyInputs','feedingTrendMetric','feedingTrendRange','feedingTrendChart','feedingTrendTooltip','feedingPlanDialog','feedingPlanForm','closeFeedingPlan','cancelFeedingPlan','clearFeedingPlan','planTargetBottle','planMinimumFeeds','planMaximumInterval','planSupplement','planDate','planProvider','planNotes','feedingPlanError','syncDialog','syncForm','closeSync','syncDisconnected','syncConnected','createSync','joinSyncKey','joinSync','syncLastRun','recoveryKey','disconnectSync','copyRecoveryKey','syncNow','syncError','exportFamilyBackup','importFamilyBackup'].reduce((a,id)=>(a[id]=$(id),a),{});

const TEMP_RANGES={
  'Rectal':{f:[97.9,100.2],c:[36.6,37.9],redF:100.4,redC:38.0},
  'Armpit (axillary)':{f:[97.6,99.4],c:[36.4,37.4],redF:99.0,redC:37.2},
  'Forehead (temporal)':{f:[96.4,98.6],c:[35.8,37.0],redF:100.4,redC:38.0},
  'Ear (tympanic)':{f:[96.4,100.2],c:[35.8,37.9],redF:100.4,redC:38.0},
  'Oral':{f:[95.9,99.5],c:[35.5,37.5],redF:100.0,redC:37.8}
};
function assessTemperature(value,unit,method){const range=TEMP_RANGES[method],n=Number(value);if(!range||!Number.isFinite(n))return null;const normal=unit==='C'?range.c:range.f,red=unit==='C'?range.redC:range.redF;if(n>=red)return{level:'danger',label:'Red flag',message:`At or above the ${red.toFixed(1)}°${unit} red-flag threshold. Contact your baby's healthcare provider promptly.`,normal};if(n<normal[0]||n>normal[1])return{level:'caution',label:'Outside normal range',message:`Outside the usual ${normal[0].toFixed(1)}–${normal[1].toFixed(1)}°${unit} range for this method. Recheck and contact your healthcare provider if concerned.`,normal};return{level:'normal',label:'In normal range',message:`Within the usual ${normal[0].toFixed(1)}–${normal[1].toFixed(1)}°${unit} range for this method.`,normal}}
function updateTempAssessment(){const method=els.tempMethod.value,unit=els.tempUnit.value,range=TEMP_RANGES[method],result=assessTemperature(els.temperature.value,unit,method);let level='neutral',title='Select a measurement method',message='Normal ranges vary by where the temperature is taken.';if(range&&!els.temperature.value){const normal=unit==='C'?range.c:range.f,red=unit==='C'?range.redC:range.redF;title=`Normal: ${normal[0].toFixed(1)}–${normal[1].toFixed(1)}°${unit}`;message=`Red-flag threshold: ${red.toFixed(1)}°${unit} or higher.`}if(result){level=result.level;title=result.label;message=result.message}els.tempAssessment.className=`temp-assessment ${level}`;els.tempAssessment.innerHTML=`<span class="assessment-dot"></span><div><strong>${title}</strong><p>${message}</p></div>`}

function normalizeFeedingState(value){const normalized=LittleDaysGrowth.analysis.normalizeState(value);normalized.feedingGuidance=normalized.feedingGuidance&&typeof normalized.feedingGuidance==='object'?normalized.feedingGuidance:{};normalized.feedingGuidance.tracking=normalized.feedingGuidance.tracking&&typeof normalized.feedingGuidance.tracking==='object'?normalized.feedingGuidance.tracking:{};normalized.schemaVersion=3;return normalized}
function loadState(){try{return normalizeFeedingState(familyStore.currentRecord())}catch{return normalizeFeedingState({schemaVersion:3,baby:{id:familyStore.activeId()},entries:[]})}}
function saveState(){state=normalizeFeedingState(familyStore.saveCurrent(state));els.saveStatus.textContent='Saved just now';renderFamilyPicker();scheduleSync();setTimeout(()=>{if(!syncRunning)els.saveStatus.textContent=familyStore.syncConfig()?'Saved · sync pending':'Saved locally'},1500)}
function birthDate(){if(state.baby.birthAt)return new Date(state.baby.birthAt);if(!state.baby.date||!state.baby.time)return null;return new Date(`${state.baby.date}T${state.baby.time}:00`)}
function babyDayAt(date){const birth=birthDate();if(!birth)return 0;return Math.floor((+date-+birth)/86400000)+1}
function currentBabyDay(){return Math.max(1,babyDayAt(new Date()))}
function pad(n){return String(n).padStart(2,'0')}
function inputParts(date=new Date()){return{date:`${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}`,time:`${pad(date.getHours())}:${pad(date.getMinutes())}`}}
function formatDate(date,options={}){return new Intl.DateTimeFormat(undefined,options).format(date)}
function dayBounds(day){const start=new Date(birthDate().getTime()+(day-1)*86400000);return{start,end:new Date(start.getTime()+86400000)}}
function entriesForDay(day){const {start,end}=dayBounds(day);return state.entries.filter(e=>{const d=new Date(e.at);return d>=start&&d<end}).sort((a,b)=>+new Date(b.at)-+new Date(a.at))}
function escapeHtml(value=''){return String(value).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function checkedValues(name){return [...document.querySelectorAll(`[name="${name}"]:checked`)].map(input=>/** @type {HTMLInputElement} */(input).value)}
function setCheckedValues(name,values=[]){const selected=new Set(Array.isArray(values)?values:[]);document.querySelectorAll(`[name="${name}"]`).forEach(input=>{const checkbox=/** @type {HTMLInputElement} */(input);checkbox.checked=selected.has(checkbox.value)})}

function render(){renderFamilyPicker();const configured=!!birthDate();els.setupCard.classList.toggle('hidden',configured);els.tracker.classList.toggle('hidden',!configured);if(!configured){els.babyDay.textContent='—';els.dayWindow.textContent='Add birth details to begin';return}const nowDay=currentBabyDay();selectedDay=Math.min(Math.max(1,selectedDay),nowDay);els.babyDay.textContent=`Day ${nowDay}`;const current=dayBounds(nowDay);els.dayWindow.textContent=`${formatDate(current.start,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} → ${formatDate(current.end,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}`;renderDayPicker(nowDay);renderSummary();renderFeedingGuidance();renderChart();renderDailyChart();renderGrowthAnalysis();}
function renderDayPicker(nowDay){els.daySelect.innerHTML=Array.from({length:nowDay},(_,i)=>`<option value="${i+1}" ${i+1===selectedDay?'selected':''}>Baby Day ${i+1}</option>`).reverse().join('');els.prevDay.disabled=selectedDay<=1;els.nextDay.disabled=selectedDay>=nowDay}
function renderSummary(){const entries=entriesForDay(selectedDay),feeds=entries.filter(e=>e.type==='feed'),wet=entries.filter(e=>e.type==='wet'),soil=entries.filter(e=>e.type==='soiled'),temps=entries.filter(e=>e.type==='temperature');els.summaryTitle.textContent=`Baby Day ${selectedDay}`;els.feedCount.textContent=feeds.length;els.wetCount.textContent=wet.length;els.soilCount.textContent=soil.length;els.tempCount.textContent=temps.length?`${temps[0].temperature}°${temps[0].tempUnit}`:'—';els.tempDetail.textContent=temps.length?`${temps.length} check${temps.length===1?'':'s'} · last at ${formatDate(new Date(temps[0].at),{hour:'numeric',minute:'2-digit'})}`:'No checks yet';const ml=feeds.filter(e=>e.method==='bottle').reduce((n,e)=>n+(Number(e.amount)||0),0),mins=feeds.filter(e=>e.method==='breast').reduce((n,e)=>n+(Number(e.duration)||0),0);els.feedDetail.textContent=feeds.length?`${ml?ml+' ml bottle':''}${ml&&mins?' · ':''}${mins?mins+' min breast':''}`:'No feeds yet';els.wetDetail.textContent=wet.length?`Last at ${formatDate(new Date(wet[0].at),{hour:'numeric',minute:'2-digit'})}`:'No wet diapers yet';els.soilDetail.textContent=soil.length?`Last at ${formatDate(new Date(soil[0].at),{hour:'numeric',minute:'2-digit'})}`:'No soiled diapers yet';els.timeline.innerHTML=entries.length?entries.map(timelineItem).join(''):`<div class="empty-state"><span>☾</span>No entries for this baby day yet.<br>Use a quick-add button above.</div>`;}
const FEED_CUE_LABELS={hands_to_mouth:'hands to mouth',rooting:'rooting',lip_smacking:'lip smacking',continued_searching:'continued searching after feed',closes_mouth:'closed mouth',turns_away:'turned away',relaxed:'relaxed hands/body',stops_sucking:'stopped sucking',releases:'released breast/bottle'};
const FEED_CONCERN_LABELS={repeated_large_vomiting:'repeated large-volume vomiting',feeding_intolerance:'significant spit-up / intolerance',poor_willingness:'poor willingness or inability to feed',lethargy:'significant lethargy',jaundice:'significant jaundice concern'};
function feedingObservationText(e){
  if(e.type!=='feed')return[];
  const details=[];
  if(e.swallowing)details.push({yes:'Swallowing observed',no:'No active swallowing observed',unsure:'Swallowing unsure'}[e.swallowing]||e.swallowing);
  if(e.latch)details.push({comfortable:'Comfortable latch',difficulty:'Latch difficulty',painful:'Painful latch',unsure:'Latch unsure'}[e.latch]||e.latch);
  if(e.afterFeed)details.push({satisfied:'Satisfied after feed',still_hungry:'Still hungry after feed',sleepy:'Sleepy after feed',unsure:'Response unsure'}[e.afterFeed]||e.afterFeed);
  if(e.bottleResponse)details.push({finished_hungry:'Finished bottle and still hungry',finished_satisfied:'Finished bottle and satisfied',stopped_before_finishing:'Stopped before finishing',unsure:'Bottle response unsure'}[e.bottleResponse]||e.bottleResponse);
  if(e.hungerCues?.length)details.push('Hunger cues: '+e.hungerCues.map(cue=>FEED_CUE_LABELS[cue]||cue).join(', '));
  if(e.fullnessCues?.length)details.push('Fullness cues: '+e.fullnessCues.map(cue=>FEED_CUE_LABELS[cue]||cue).join(', '));
  if(e.feedingConcerns?.length)details.push('Concerns: '+e.feedingConcerns.map(concern=>FEED_CONCERN_LABELS[concern]||concern).join(', '));
  return details
}
function timelineItem(e){
  const d=new Date(e.at),title=e.type==='feed'?(e.method==='bottle'?'Bottle feeding':'Breastfeeding'):e.type==='wet'?'Wet diaper':e.type==='soiled'?'Soiled diaper':e.type==='temperature'?'Temperature check':'Growth measurement';
  let details=[],badge='';
  if(e.method==='bottle'&&e.amount)details.push(`${e.amount} ml${e.milkType?' · '+e.milkType:''}`);
  if(e.method==='breast'&&e.duration)details.push(`${e.duration} minutes${e.side?' · '+e.side:''}`);
  if(e.type==='feed'){
    details.push(...feedingObservationText(e));
    if(e.feedingConcerns?.length)badge='<span class="temp-badge caution">Concern recorded</span>';
  }
  if(e.color)details.push(e.color);
  if(e.type==='temperature'){details.push(`${e.temperature}°${e.tempUnit}${e.tempMethod?' · '+e.tempMethod:''}`);const result=assessTemperature(e.temperature,e.tempUnit,e.tempMethod);if(result)badge=`<span class="temp-badge ${result.level}">${result.label}</span>`}
  if(e.type==='growth'){if(e.weight)details.push(`${e.weight} ${e.weightUnit||'kg'}`);if(e.height)details.push(`${e.height} ${e.heightUnit||'cm'}`);if(e.headCircumference)details.push(`Head ${e.headCircumference} ${e.headUnit||'cm'}`);if(e.includeInGrowthAnalysis===false)badge='<span class="temp-badge excluded">Excluded from analysis</span>'}
  if(e.notes)details.push(e.notes);
  const safeId=escapeHtml(e.id);return `<article class="timeline-item"><div class="timeline-time">${formatDate(d,{hour:'numeric',minute:'2-digit'})}<small>${formatDate(d,{month:'short',day:'numeric'})}</small></div><span class="timeline-dot"></span><div class="timeline-copy"><strong>${title}${badge}</strong><p>${escapeHtml(details.join(' — ')||'No additional details')}</p></div><div class="entry-actions"><button class="edit-entry" data-edit="${safeId}" aria-label="Edit entry" title="Edit entry">✎</button><button class="delete-entry" data-delete="${safeId}" aria-label="Delete entry" title="Delete entry">×</button></div></article>`
}

function renderFamilyPicker(){
  const active=familyStore.activeId(),babies=familyStore.list();els.babySelector.innerHTML=babies.map(item=>`<option value="${escapeHtml(item.id)}" ${item.id===active?'selected':''}>${escapeHtml(item.name||'New baby')} — ${escapeHtml(item.id)}</option>`).join('');els.activeBabyId.textContent=`Baby ID ${active}`;
  const config=familyStore.syncConfig();els.syncSummary.textContent=config?`Encrypted family sync connected${config.lastSyncedAt?` · last synced ${formatDate(new Date(config.lastSyncedAt),{dateStyle:'medium',timeStyle:'short'})}`:' · waiting for first sync'}`:'Saved on this device only.'
}
function switchBaby(id){if(id===familyStore.activeId())return;familyStore.saveCurrent(state);if(!familyStore.setActive(id))return;state=loadState();selectedDay=birthDate()?currentBabyDay():1;editingEntryId=null;populateBabyForm();render()}
function addBaby(){familyStore.saveCurrent(state);familyStore.addBaby();state=loadState();selectedDay=1;editingEntryId=null;populateBabyForm();render();els.setupCard.scrollIntoView({behavior:'smooth'});els.babyId.focus()}
function saveBaby(){
  const requestedId=familyStore.normalizeBabyId(els.babyId.value),name=els.babyName.value.trim(),date=els.birthDate.value,time=els.birthTime.value;if(!familyStore.validBabyId(requestedId)){els.setupError.textContent='Baby ID must be 3–32 letters, numbers, hyphens, or underscores.';return}if(!date||!time){els.setupError.textContent='Please add both the birth date and time.';return}const birth=new Date(`${date}T${time}:00`),gestWeeks=els.gestationalWeeks.value?Number(els.gestationalWeeks.value):null,gestDays=Number(els.gestationalDays.value||0);if(Number.isNaN(+birth)||birth>new Date()){els.setupError.textContent='Birth date and time cannot be in the future.';return}if(gestWeeks!==null&&(gestWeeks<20||gestWeeks>42||gestDays<0||gestDays>6)){els.setupError.textContent='Please enter gestational age as 20–42 weeks and 0–6 additional days.';return}
  try{if(familyStore.isDraft())familyStore.renameActive(requestedId)}catch(error){els.setupError.textContent=error.message;return}
  state.baby={...state.baby,id:familyStore.activeId(),name,date,time,birthAt:birth.toISOString(),sex:els.babySex.value,gestationalWeeks:gestWeeks,gestationalDays:gestDays,birthWeightKg:els.birthWeight.value?Number(els.birthWeight.value):null,birthLengthCm:els.birthLength.value?Number(els.birthLength.value):null,birthHeadCm:els.birthHead.value?Number(els.birthHead.value):null,weightDisplayUnit:els.weightDisplayUnit.value,lengthDisplayUnit:els.lengthDisplayUnit.value};els.setupError.textContent='';selectedDay=currentBabyDay();saveState();populateBabyForm();render()
}
function populateBabyForm(){const b=state.baby||{};els.babyId.value=familyStore.activeId();els.babyId.disabled=!familyStore.isDraft();els.babyName.value=b.name||'';els.birthDate.value=b.date||'';els.birthTime.value=b.time||'';els.babySex.value=b.sex||'';els.gestationalWeeks.value=b.gestationalWeeks??'';els.gestationalDays.value=b.gestationalDays??0;els.birthWeight.value=b.birthWeightKg??'';els.birthLength.value=b.birthLengthCm??'';els.birthHead.value=b.birthHeadCm??'';els.weightDisplayUnit.value=b.weightDisplayUnit||'kg';els.lengthDisplayUnit.value=b.lengthDisplayUnit||'cm'}
function editBaby(){populateBabyForm();els.setupCard.classList.remove('hidden');els.setupCard.scrollIntoView({behavior:'smooth'})}
function openEntry(type){
  const now=new Date(),parts=inputParts(now);editingEntryId=null;$('submitEntry').textContent='Save entry';els.entryForm.reset();els.entryType.value=type;els.entryDate.value=parts.date;els.entryTime.value=parts.time;els.feedFields.classList.toggle('hidden',type!=='feed');els.soilFields.classList.toggle('hidden',type!=='soiled');els.tempFields.classList.toggle('hidden',type!=='temperature');els.growthFields.classList.toggle('hidden',type!=='growth');
  if(type==='feed')els.feedingObservationDetails.open=false;
  if(type==='growth'){els.weightUnit.value=state.baby.weightDisplayUnit||'kg';els.heightUnit.value=state.baby.lengthDisplayUnit||'cm';els.headUnit.value=state.baby.lengthDisplayUnit||'cm';els.includeInGrowthAnalysis.checked=true}
  els.dialogTitle.textContent=type==='feed'?'Add a feeding':type==='wet'?'Add a wet diaper':type==='soiled'?'Add a soiled diaper':type==='temperature'?'Add a temperature check':'Add growth measurement';els.dialogEyebrow.textContent='New entry';els.entryError.textContent='';toggleMethod();updateTempAssessment();els.entryDialog.showModal()
}
function editEntry(id){
  const entry=state.entries.find(e=>e.id===id);if(!entry)return;openEntry(entry.type);editingEntryId=id;const parts=inputParts(new Date(entry.at));els.entryDate.value=parts.date;els.entryTime.value=parts.time;els.notes.value=entry.notes||'';
  if(entry.type==='feed'){
    const radio=/** @type {HTMLInputElement|null} */(document.querySelector(`[name="method"][value="${entry.method||'breast'}"]`));if(radio)radio.checked=true;els.duration.value=entry.duration||'';els.side.value=entry.side||'';els.amount.value=entry.amount||'';els.milkType.value=entry.milkType||'';els.swallowing.value=entry.swallowing||'';els.latch.value=entry.latch||'';els.afterFeed.value=entry.afterFeed||'';els.bottleResponse.value=entry.bottleResponse||'';setCheckedValues('hungerCue',entry.hungerCues);setCheckedValues('fullnessCue',entry.fullnessCues);setCheckedValues('feedingConcern',entry.feedingConcerns);els.feedingObservationDetails.open=!!(entry.swallowing||entry.latch||entry.afterFeed||entry.bottleResponse||entry.hungerCues?.length||entry.fullnessCues?.length||entry.feedingConcerns?.length);toggleMethod()
  }
  if(entry.type==='soiled')els.soilColor.value=entry.color||'';
  if(entry.type==='temperature'){els.temperature.value=entry.temperature||'';els.tempUnit.value=entry.tempUnit||'F';els.tempMethod.value=entry.tempMethod||'';updateTempAssessment()}
  if(entry.type==='growth'){const weightUnit=entry.weightUnit||state.baby.weightDisplayUnit||'kg',lengthUnit=entry.heightUnit||state.baby.lengthDisplayUnit||'cm',headUnit=entry.headUnit||state.baby.lengthDisplayUnit||'cm';els.weightUnit.value=weightUnit;els.heightUnit.value=lengthUnit;els.headUnit.value=headUnit;els.weight.value=entry.weight||((entry.weightKg&&weightUnit==='lb')?LittleDaysGrowth.units.kgToLb(entry.weightKg).toFixed(2):entry.weightKg||'');els.height.value=entry.height||((entry.lengthCm&&lengthUnit==='in')?LittleDaysGrowth.units.cmToIn(entry.lengthCm).toFixed(1):entry.lengthCm||'');els.headCircumference.value=entry.headCircumference||((entry.headCm&&headUnit==='in')?LittleDaysGrowth.units.cmToIn(entry.headCm).toFixed(1):entry.headCm||'');els.includeInGrowthAnalysis.checked=entry.includeInGrowthAnalysis!==false}
  els.dialogEyebrow.textContent='Edit entry';els.dialogTitle.textContent=entry.type==='feed'?'Edit feeding':entry.type==='wet'?'Edit wet diaper':entry.type==='soiled'?'Edit soiled diaper':entry.type==='temperature'?'Edit temperature check':'Edit growth measurement';$('submitEntry').textContent='Save changes'
}
function toggleMethod(){const bottle=$('bottleMethod').checked;els.bottleDetails.classList.toggle('hidden',!bottle);els.breastDetails.classList.toggle('hidden',bottle);els.bottleObservationFields.classList.toggle('hidden',!bottle);els.breastObservationFields.classList.toggle('hidden',bottle)}
function saveEntry(event){
  event.preventDefault();const at=new Date(`${els.entryDate.value}T${els.entryTime.value}:00`),birth=birthDate();if(Number.isNaN(+at)||at<birth){els.entryError.textContent='Entry time must be after the birth time.';return}if(at>new Date(Date.now()+60000)){els.entryError.textContent='Entry time cannot be in the future.';return}
  const type=els.entryType.value,method=type==='feed'?/** @type {HTMLInputElement} */(document.querySelector('[name="method"]:checked')).value:'';if(type==='feed'&&method==='bottle'&&!els.amount.value){els.entryError.textContent='Please enter the bottle amount in ml.';return}if(type==='feed'&&method==='breast'&&!els.duration.value){els.entryError.textContent='Please enter breastfeeding duration in minutes.';return}if(type==='temperature'&&!els.temperature.value){els.entryError.textContent='Please enter the temperature.';return}if(type==='temperature'&&!els.tempMethod.value){els.entryError.textContent='Please select the measurement method.';return}if(type==='growth'&&!els.weight.value&&!els.height.value&&!els.headCircumference.value){els.entryError.textContent='Please enter a weight, length, head circumference, or a combination.';return}
  const temp=Number(els.temperature.value);if(type==='temperature'&&((els.tempUnit.value==='F'&&(temp<86||temp>110))||(els.tempUnit.value==='C'&&(temp<30||temp>43.3)))){els.entryError.textContent='Please enter a valid temperature.';return}
  const previous=editingEntryId?state.entries.find(e=>e.id===editingEntryId)||{}:{},entry={...previous,id:editingEntryId||(crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`),type,at:at.toISOString(),updatedAt:new Date().toISOString(),method,amount:els.amount.value,duration:els.duration.value,side:els.side.value,milkType:els.milkType.value,swallowing:type==='feed'&&method==='breast'?els.swallowing.value:'',latch:type==='feed'&&method==='breast'?els.latch.value:'',afterFeed:type==='feed'&&method==='breast'?els.afterFeed.value:'',bottleResponse:type==='feed'&&method==='bottle'?els.bottleResponse.value:'',hungerCues:type==='feed'?checkedValues('hungerCue'):[],fullnessCues:type==='feed'?checkedValues('fullnessCue'):[],feedingConcerns:type==='feed'?checkedValues('feedingConcern'):[],color:els.soilColor.value,temperature:els.temperature.value,tempUnit:els.tempUnit.value,tempMethod:els.tempMethod.value,weight:els.weight.value,weightUnit:els.weightUnit.value,height:els.height.value,heightUnit:els.heightUnit.value,headCircumference:els.headCircumference.value,headUnit:els.headUnit.value,weightKg:type==='growth'&&els.weight.value?LittleDaysGrowth.units.weightKg(els.weight.value,els.weightUnit.value):null,lengthCm:type==='growth'&&els.height.value?LittleDaysGrowth.units.lengthCm(els.height.value,els.heightUnit.value):null,headCm:type==='growth'&&els.headCircumference.value?LittleDaysGrowth.units.lengthCm(els.headCircumference.value,els.headUnit.value):null,includeInGrowthAnalysis:type==='growth'?els.includeInGrowthAnalysis.checked:previous.includeInGrowthAnalysis,notes:els.notes.value.trim()};
  if(editingEntryId){const index=state.entries.findIndex(e=>e.id===editingEntryId);if(index>=0)state.entries[index]=entry}else state.entries.push(entry);editingEntryId=null;$('submitEntry').textContent='Save entry';selectedDay=Math.max(1,babyDayAt(at));saveState();els.entryDialog.close();render()
}
function deleteEntry(id){if(!confirm('Delete this entry?'))return;state.entries=state.entries.filter(e=>e.id!==id);familyStore.markEntryDeleted(id);saveState();render()}
function clearAll(){const label=state.baby.name||familyStore.activeId();if(!confirm(`Delete ${label}'s profile and every care entry? Other babies will not be affected. This cannot be undone.`))return;familyStore.deleteActive();state=loadState();selectedDay=birthDate()?currentBabyDay():1;populateBabyForm();render();scheduleSync()}

function hasClinicalFeedingPlan(plan=state.baby?.clinicalFeedingPlan){return !!plan&&['targetBottleMl','minimumFeedsPerDay','maximumIntervalHours','supplementMl','notes'].some(key=>plan[key]!==null&&plan[key]!==undefined&&String(plan[key]).trim()!=='')}
