  const numberOrNull=input=>input.value===''?null:Number(input.value),plan={targetBottleMl:numberOrNull(els.planTargetBottle),minimumFeedsPerDay:numberOrNull(els.planMinimumFeeds),maximumIntervalHours:numberOrNull(els.planMaximumInterval),supplementMl:numberOrNull(els.planSupplement),dateProvided:els.planDate.value,providerNote:els.planProvider.value.trim(),notes:els.planNotes.value.trim()};
