async function importFamilyBackup(event){
  const input=event.target,file=input.files?.[0];if(!file)return;els.syncError.textContent='';
  try{if(file.size>20*1024*1024)throw new Error('That backup is too large.');const backup=JSON.parse(await file.text());if(backup?.format!=='little-days-family-backup-v1'||!backup.family?.babies)throw new Error('Choose a Little Days family backup file.');if(!confirm('Merge the babies and entries from this backup with the records on this device?'))return;familyStore.saveCurrent(state);familyStore.mergeSnapshot(backup.family);state=loadState();selectedDay=birthDate()?currentBabyDay():1;populateBabyForm();render();scheduleSync(100);els.saveStatus.textContent='Backup imported'}catch(error){els.syncError.textContent=error.message}finally{input.value=''}
}
